CREATE TABLE IF NOT EXISTS tenants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB;
GRANT SELECT, INSERT, UPDATE, DELETE ON `tenants` TO lingedge_app;
CREATE TABLE IF NOT EXISTS t (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NULL, code VARCHAR(64) NOT NULL, uniq_key VARCHAR(160) AS (CONCAT(COALESCE(tenant_id,0),':',code)) STORED NOT NULL, UNIQUE KEY uk (uniq_key), CONSTRAINT fk FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
